def sortJumbled(mapping, nums):
    def mapped(x):
        if x == 0:
            return mapping[0]
        digits = []
        while x:
            digits.append(x % 10)
            x //= 10
        v = 0
        for d in reversed(digits):
            v = v * 10 + mapping[d]
        return v
    return sorted(nums, key=mapped)
